<script setup lang="ts">
import { router, useForm } from '@inertiajs/vue3';
import { reactive, ref } from 'vue';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import type { AdminOperationsProps } from '../../../types/admin';

const props = defineProps<AdminOperationsProps>();
const filters = reactive({ ...props.filters });
const loading = ref(false);
const exportForm = useForm({ ...props.filters, idempotency_key: `audit-${Date.now()}` });

function applyFilters(): void {
    loading.value = true;
    router.get('/admin/operations', { ...filters }, { preserveState: true, preserveScroll: true, replace: true, onFinish: () => { loading.value = false; } });
}

function goTo(url: string | null): void {
    if (url) router.get(url, {}, { preserveState: true, preserveScroll: true });
}

function queueExport(): void {
    exportForm.transform(() => ({ ...filters, idempotency_key: exportForm.idempotency_key })).post('/admin/operations/audit/export', { preserveScroll: true });
}

function formatDate(value: string | null): string {
    return value ? new Date(value).toLocaleString() : 'Chưa ghi nhận';
}

function severityClass(value: string): string {
    return { critical: 'bg-red-50 text-red-700', warning: 'bg-amber-50 text-amber-700', info: 'bg-slate-100 text-slate-600' }[value] ?? 'bg-slate-100 text-slate-600';
}
</script>

<template>
    <AdminLayout :breadcrumb="[{ label: 'Admin', href: '/admin' }, { label: 'Audit & system' }]">
        <div class="grid gap-6">
            <p class="sr-only" id="audit-table-description">Audit events filtered by the selected window</p>
            <section class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="text-xs font-bold uppercase tracking-[0.2em] text-brand-600">Operations</p><h1 class="mt-2 text-3xl font-bold tracking-tight text-slate-950">Audit explorer & system health</h1><p class="mt-2 max-w-2xl text-sm text-slate-500">Evidence vận hành được lọc ổn định, redacted và liên kết trực tiếp tới Action Center/runbook.</p></div><span class="rounded-full px-3 py-2 text-xs font-bold" :class="props.health.status === 'healthy' ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-700'">{{ props.health.status }}</span></section>

            <section class="grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:grid-cols-2 lg:grid-cols-4"><label class="grid gap-1 text-xs font-semibold text-slate-600">Khoảng thời gian<select v-model="filters.range" class="mt-1 min-h-11 rounded-xl border-slate-200 text-sm font-normal"><option value="7d">7 ngày</option><option value="30d">30 ngày</option><option value="90d">90 ngày</option></select></label><label class="grid gap-1 text-xs font-semibold text-slate-600">Event<input v-model="filters.event" class="mt-1 min-h-11 rounded-xl border-slate-200 text-sm font-normal" placeholder="auth.login" /></label><label class="grid gap-1 text-xs font-semibold text-slate-600">Actor<select v-model="filters.actor_id" class="mt-1 min-h-11 rounded-xl border-slate-200 text-sm font-normal"><option :value="null">Tất cả actor</option><option v-for="actor in props.filterOptions.actors" :key="actor.value" :value="Number(actor.value)">{{ actor.label }}</option></select></label><label class="grid gap-1 text-xs font-semibold text-slate-600">Severity<select v-model="filters.severity" class="mt-1 min-h-11 rounded-xl border-slate-200 text-sm font-normal"><option value="">Tất cả severity</option><option v-for="severity in props.filterOptions.severities" :key="severity.value" :value="severity.value">{{ severity.label }}</option></select></label><label class="grid gap-1 text-xs font-semibold text-slate-600">Target type<select v-model="filters.target_type" class="mt-1 min-h-11 rounded-xl border-slate-200 text-sm font-normal"><option value="">Tất cả target</option><option v-for="target in props.filterOptions.targetTypes" :key="target.value" :value="target.value">{{ target.label }}</option></select></label><label class="grid gap-1 text-xs font-semibold text-slate-600">Target ID<input v-model.number="filters.target_id" type="number" min="1" class="mt-1 min-h-11 rounded-xl border-slate-200 text-sm font-normal" /></label><label class="grid gap-1 text-xs font-semibold text-slate-600">Timezone<select v-model="filters.timezone" class="mt-1 min-h-11 rounded-xl border-slate-200 text-sm font-normal"><option value="UTC">UTC</option><option value="Asia/Ho_Chi_Minh">Asia/Ho_Chi_Minh</option><option value="Asia/Bangkok">Asia/Bangkok</option></select></label><button type="button" class="min-h-11 self-end rounded-xl bg-brand-600 px-4 text-sm font-semibold text-white hover:bg-brand-700 disabled:opacity-60" :disabled="loading" @click="applyFilters">{{ loading ? 'Đang lọc…' : 'Áp dụng bộ lọc' }}</button></section>

            <section class="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><p class="text-xs font-semibold uppercase tracking-wide text-slate-400">Queue depth</p><p class="mt-3 text-2xl font-bold">{{ props.health.queue.depth }}</p><a :href="props.health.queue.href" class="mt-2 block text-xs font-semibold text-brand-700">{{ props.health.queue.failed }} failed → Action Center</a></article><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><p class="text-xs font-semibold uppercase tracking-wide text-slate-400">Webhook failures</p><p class="mt-3 text-2xl font-bold text-amber-700">{{ props.health.webhooks.failedLast7d }}</p><a :href="props.health.webhooks.href" class="mt-2 block text-xs font-semibold text-brand-700">Mở incident list →</a></article><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><p class="text-xs font-semibold uppercase tracking-wide text-slate-400">Scheduler</p><p class="mt-3 text-lg font-bold" :class="props.health.scheduler.status === 'healthy' ? 'text-emerald-700' : 'text-amber-700'">{{ props.health.scheduler.status }}</p><p class="mt-2 text-xs text-slate-500">{{ formatDate(props.health.scheduler.lastHealthCheck) }}</p></article><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><p class="text-xs font-semibold uppercase tracking-wide text-slate-400">Retention</p><p class="mt-3 text-lg font-bold" :class="props.health.retention.status === 'healthy' ? 'text-emerald-700' : 'text-amber-700'">{{ props.health.retention.status }}</p><a :href="props.health.retention.runbookHref" class="mt-2 block text-xs font-semibold text-brand-700">Mở runbook →</a></article><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><p class="text-xs font-semibold uppercase tracking-wide text-slate-400">AI provider</p><p class="mt-3 text-lg font-bold">{{ props.health.provider.status }}</p><a :href="props.health.provider.href" class="mt-2 block text-xs font-semibold text-brand-700">Mở AI operations →</a></article></section>

            <section id="retention" class="grid gap-4 lg:grid-cols-[1fr_20rem]"><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="flex items-center justify-between gap-3"><div><h2 class="font-bold text-slate-950">Retention policy</h2><p class="mt-1 text-xs text-slate-500">Xoá sớm không mở từ UI; CSKH phải theo runbook.</p></div><a :href="props.health.links.runbook" class="text-sm font-semibold text-brand-700">Runbook →</a></div><div class="mt-5 grid grid-cols-2 gap-3 text-sm"><div class="rounded-xl bg-slate-50 p-3"><span class="block text-xs text-slate-500">Audit</span><strong>{{ props.health.retentionPolicy.auditMonths }} tháng</strong></div><div class="rounded-xl bg-slate-50 p-3"><span class="block text-xs text-slate-500">Exam attempt/answer</span><strong>{{ props.health.retentionPolicy.examYears }} năm</strong></div><div class="rounded-xl bg-slate-50 p-3"><span class="block text-xs text-slate-500">Expired audit</span><strong>{{ props.health.retention.expired.audit }}</strong></div><div class="rounded-xl bg-slate-50 p-3"><span class="block text-xs text-slate-500">Expired exam data</span><strong>{{ props.health.retention.expired.examAttempts + props.health.retention.expired.examAnswers }}</strong></div></div></article><article class="rounded-2xl border border-sky-200 bg-sky-50 p-5"><p class="text-xs font-bold uppercase tracking-wide text-sky-700">Audit export</p><h2 class="mt-2 font-bold text-slate-950">Async, capped at 10,000 rows</h2><p class="mt-2 text-sm text-slate-700">Export chỉ chứa dữ liệu đã redact và link download có expiry.</p><button type="button" class="mt-5 min-h-10 rounded-xl bg-slate-900 px-4 text-sm font-semibold text-white hover:bg-slate-700 disabled:opacity-60" :disabled="exportForm.processing" @click="queueExport">{{ exportForm.processing ? 'Đang xếp hàng…' : 'Queue CSV export' }}</button></article></section>

            <section class="rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="border-b border-slate-100 p-5"><div class="flex items-center justify-between"><div><h2 class="font-bold text-slate-950">Audit log</h2><p class="mt-1 text-xs text-slate-500">{{ props.audits.meta.total }} records · stable ordering theo occurred_at và id.</p></div><a :href="props.health.links.actionCenter" class="text-sm font-semibold text-brand-700">Action Center →</a></div></div><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">Event</th><th class="px-5 py-3">Severity</th><th class="px-5 py-3">Actor</th><th class="px-5 py-3">Target</th><th class="px-5 py-3">Occurred</th><th class="px-5 py-3"></th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="audit in props.audits.data" :key="audit.id"><td class="px-5 py-3 font-semibold text-slate-900">{{ audit.event }}</td><td class="px-5 py-3"><span class="rounded-full px-2 py-1 text-xs font-bold" :class="severityClass(audit.severity)">{{ audit.severity }}</span></td><td class="px-5 py-3 text-slate-600">{{ audit.actor }}</td><td class="px-5 py-3 text-slate-600">{{ audit.targetType || '—' }}{{ audit.targetId ? ` #${audit.targetId}` : '' }}</td><td class="px-5 py-3 text-xs text-slate-500">{{ formatDate(audit.occurredAt) }}</td><td class="px-5 py-3 text-right"><a :href="audit.detailHref" class="font-semibold text-brand-700 hover:underline">Detail</a></td></tr><tr v-if="!props.audits.data.length"><td colspan="6" class="px-5 py-10 text-center text-sm text-slate-500">Không có audit trong khoảng đã chọn.</td></tr></tbody></table></div><div class="flex items-center justify-between gap-3 border-t border-slate-100 p-4"><button type="button" class="rounded-lg px-3 py-2 text-sm font-semibold text-slate-600 ring-1 ring-slate-200 disabled:opacity-40" :disabled="!props.audits.links.previous" @click="goTo(props.audits.links.previous)">← Trước</button><span class="text-xs text-slate-500">Trang {{ props.audits.meta.currentPage }} / {{ props.audits.meta.lastPage }}</span><button type="button" class="rounded-lg px-3 py-2 text-sm font-semibold text-slate-600 ring-1 ring-slate-200 disabled:opacity-40" :disabled="!props.audits.links.next" @click="goTo(props.audits.links.next)">Sau →</button></div></section>
        </div>
    </AdminLayout>
</template>
